<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {Search,LayoutGrid,UsersRound,HardDrive,Wrench,Download,Rss,Compass,Settings2,ListTodo,Menu,Bell,Plus,RefreshCw,ChevronDown,SlidersHorizontal,ArrowUpRight,Play,Star,X,Check,CircleAlert,LoaderCircle,Film,Database,ShieldCheck,Sparkles,FolderOpen,Clock3,Monitor,LogOut,Eye,EyeOff} from 'lucide-vue-next'
import {request,json,ApiError,type Work,type Actor,type Device,type Library,type Job,type Candidate} from './api'
type Section='library'|'actors'|'devices'|'tools'|'downloads'|'feeds'|'discover'|'jobs'|'settings'
const section=ref<Section>('library'),mobileNav=ref(false),busy=ref(false),notice=ref(''),error=ref(''),query=ref(''),statusFilter=ref(''),actorFilter=ref(''),selected=ref<Work|null>(null),modal=ref(false),auth=ref(!!localStorage.getItem('mediashelf_token')),setup=ref(false),password=ref(''),showPassword=ref(false),working=ref(false)
const works=ref<Work[]>([]),actors=ref<Actor[]>([]),devices=ref<Device[]>([]),libraries=ref<Library[]>([]),tools=ref<any[]>([]),jobs=ref<Job[]>([]),downloaders=ref<any[]>([]),torrents=ref<any[]>([]),feeds=ref<any[]>([]),candidates=ref<Candidate[]>([]),recommendations=ref<any[]>([]),actorRecs=ref<any[]>([]),catalog=ref<any[]>([]),settings=ref<any>({}),sources=ref<any[]>([]),syncs=ref<any[]>([]),pollTimer=ref<number|undefined>()
const nav=[{id:'library',label:'媒体库',icon:LayoutGrid},{id:'actors',label:'演员收藏',icon:UsersRound},{id:'devices',label:'设备与目录',icon:HardDrive},{id:'tools',label:'本地工具',icon:Wrench},{id:'downloads',label:'下载管理',icon:Download},{id:'feeds',label:'RSS 订阅',icon:Rss},{id:'discover',label:'发现与推荐',icon:Compass},{id:'jobs',label:'任务队列',icon:ListTodo},{id:'settings',label:'设置',icon:Settings2}] as const
const filtered=computed(()=>works.value.filter(w=>(!query.value||`${w.code} ${w.title} ${w.actors?.join(' ')}`.toLowerCase().includes(query.value.toLowerCase()))&&(!statusFilter.value||w.collection_status===statusFilter.value)&&(!actorFilter.value||w.actors?.includes(actorFilter.value))))
const totalSize=computed(()=>{const n=works.value.reduce((sum,w)=>sum+(w.files||[]).reduce((a,f)=>a+(f.size||0),0),0);return n?(n/1024**4).toFixed(2)+' TB':'—'})
async function refresh(){error.value='';busy.value=true;try{if(!auth.value){setup.value=true;return}const paths=['/works','/actors','/devices','/libraries','/tools','/jobs','/downloaders','/feeds','/candidates','/recommendations','/actor-recommendations','/settings','/sources','/catalog-syncs'];const results=await Promise.allSettled(paths.map(p=>request<any>(p)));const targets=[works,actors,devices,libraries,tools,jobs,downloaders,feeds,candidates,recommendations,actorRecs,settings,sources,syncs];results.forEach((r,i)=>{if(r.status==='fulfilled')targets[i].value=r.value;else if(r.reason instanceof ApiError&&r.reason.status===401){auth.value=false;setup.value=true;localStorage.removeItem('mediashelf_token')}else error.value=error.value||`${paths[i]} 加载失败：${r.reason?.message||r.reason}`});if(downloaders.value[0])try{torrents.value=await request(`/downloaders/${encodeURIComponent(downloaders.value[0].id)}/torrents`)}catch(e:any){error.value=error.value||`下载器读取失败：${e.message}`}}catch(e:any){error.value=e.message||String(e)}finally{busy.value=false}}
async function login(){working.value=true;error.value='';try{const r=await request<{token:string}>('/login',json('POST',{password:password.value}));localStorage.setItem('mediashelf_token',r.token);auth.value=true;setup.value=false;password.value='';await refresh()}catch(e:any){error.value=e.message}finally{working.value=false}}
function logout(){localStorage.removeItem('mediashelf_token');auth.value=false;setup.value=true;works.value=[]}
async function action(path:string,body?:any,method='POST'){working.value=true;error.value='';try{await request(path,json(method,body));notice.value='操作已提交';await refresh()}catch(e:any){const message=e.message;await refresh();error.value=message}finally{working.value=false}}
async function selectWork(w:Work){selected.value=w;w.progress ||= {compression:'pending',cutting:'pending',translation:'pending',verified:false};for(const f of w.files||[])f.progress ||= {compression:'pending',cutting:'pending',translation:'pending',verified:false};modal.value=true}
async function saveWork(){if(!selected.value)return;try{await request(`/works/${encodeURIComponent(selected.value.id)}`,json('PATCH',{rating:selected.value.rating,progress:selected.value.progress,collection_status:selected.value.collection_status,title:selected.value.title,actors:selected.value.actors,tags:selected.value.tags}));notice.value='作品信息已保存';modal.value=false;await refresh()}catch(e:any){error.value=e.message}}
function coverSrc(url?:string){if(!url)return '';try{const u=new URL(url,location.origin);if(u.origin===location.origin&&u.pathname.startsWith('/covers/')){const token=localStorage.getItem('mediashelf_token');if(token)u.searchParams.set('token',token)}return u.href}catch{return url||''}}
function openListUrl(file:any){const lib=libraries.value.find(l=>l.id===file.library_id);if(!lib?.openlist_base)return '';try{const u=new URL(lib.openlist_base);if(!['http:','https:'].includes(u.protocol))return '';const prefix=(lib.openlist_prefix||'').replace(/^\/+|\/+$/g,'');const rel=String(file.relative_path||'').split(/[\\/]+/).filter(Boolean).map(encodeURIComponent).join('/');const parts=[prefix.split('/').filter(Boolean).map(encodeURIComponent).join('/'),rel].filter(Boolean).join('/');u.pathname=`${u.pathname.replace(/\/$/,'')}/${parts}`;return u.href}catch{return ''}}
async function saveFileProgress(work:Work,file:any){try{const progress=file.progress||{compression:'pending',cutting:'pending',translation:'pending',verified:false};await request(`/works/${encodeURIComponent(work.id)}/files/${encodeURIComponent(file.id)}`,json('PATCH',{progress}));notice.value='文件处理进度已保存'}catch(e:any){error.value=e.message;await refresh()}}
async function saveActor(a:Actor){try{await request(`/actors/${encodeURIComponent(a.name)}`,json('PATCH',{policy:a.policy,target:a.target}));notice.value=`${a.name} 的策略已保存`}catch(e:any){error.value=e.message}}
async function add(kind:string){const name=prompt('名称');if(!name)return;try{if(kind==='device'){const r=await request<any>('/devices',json('POST',{name}));notice.value=`设备已创建。请保存令牌：${r.token}`}else if(kind==='library'){const path=prompt('设备上的本地目录路径');if(!path)return;const device_id=prompt('设备 ID（必填；可从设备与目录页复制）');if(!device_id)return;await request('/libraries',json('POST',{name,path,device_id}));notice.value='目录已添加'}else if(kind==='tool'){const path=prompt('工具程序路径');if(!path)return;const device_id=prompt('设备 ID');if(!device_id)return;await request('/tools',json('POST',{name,path,device_id,working_dir:''}));notice.value='工具已添加'}else if(kind==='feed'){const url=prompt('RSS 地址');if(!url)return;const include=prompt('包含关键词（可留空）')||'',exclude=prompt('排除关键词（可留空）')||'';await request('/feeds',json('POST',{name,url,include,exclude}));notice.value='订阅已添加'}else if(kind==='downloader'){const url=prompt('qBittorrent WebUI 地址');if(!url)return;await request('/downloaders',json('POST',{name,url,username:prompt('用户名')||'',password:prompt('密码')||'',device_id:prompt('设备 ID（本机下载器可留空）')||''}));notice.value='下载器已添加'}await refresh()}catch(e:any){error.value=e.message}}
async function saveSettings(){try{await request('/settings',json('PATCH',settings.value));notice.value='设置已保存'}catch(e:any){error.value=e.message}}
async function backup(){try{const d=await request<any>('/backup'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download=`mediashelf-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}catch(e:any){error.value=e.message}}
async function restore(ev:Event){const f=(ev.target as HTMLInputElement).files?.[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!confirm('恢复会覆盖当前数据库，确定继续吗？'))return;await request('/restore',json('POST',d));notice.value='恢复完成';await refresh()}catch(e:any){error.value=e.message}}
async function loadCatalog(){try{catalog.value=await request(`/catalog${actorFilter.value?'?actor='+encodeURIComponent(actorFilter.value):''}`)}catch(e:any){error.value=e.message}}
async function addTorrent(){if(!downloaders.value[0])return;const url=prompt('种子链接或磁力链接');if(!url)return;const code=prompt('作品编号（用于本地重复检查，可留空）')||'';const save_path=prompt('保存路径（可留空使用下载器默认路径）')||'';const category=prompt('分类（可留空）')||'';const tags=prompt('标签，多个用逗号分隔（可留空）')||'';await action(`/downloaders/${encodeURIComponent(downloaders.value[0].id)}/add`,{url,code,save_path,category,tags})}
function confirmDelete(t:any){if(window.confirm(`确定从下载器移除「${t.name}」？本地文件会保留。`))return action(`/downloaders/${encodeURIComponent(downloaders.value[0].id)}/action`,{action:'delete',hashes:[t.hash],delete_files:false})}
async function manageTorrent(t:any,op:'category'|'tags'|'limits'){if(!downloaders.value[0])return;const id=encodeURIComponent(downloaders.value[0].id);if(op==='category'){const category=prompt('设置分类',t.category||'');if(category===null)return;await action(`/downloaders/${id}/action`,{action:'category',hashes:[t.hash],category})}else if(op==='tags'){const tags=prompt('添加标签，多个用逗号分隔',t.tags||'');if(tags===null)return;await action(`/downloaders/${id}/action`,{action:'tags',hashes:[t.hash],tags})}else{const dl=prompt('下载限速（MiB/s，0 表示不限）','0');if(dl===null)return;const ul=prompt('上传限速（MiB/s，0 表示不限）','0');if(ul===null)return;const download_limit=Math.max(0,Number(dl)||0)*1024*1024,upload_limit=Math.max(0,Number(ul)||0)*1024*1024;await action(`/downloaders/${id}/action`,{action:'limits',hashes:[t.hash],download_limit,upload_limit})}}
async function addSource(){const source=prompt('来源标识：javdb、javlibrary 或 fanza');if(!source)return;const base_url=prompt('来源地址（可留空使用默认）')||'';const proxy_url=prompt('HTTP(S) 代理地址（可留空）')||'';const cookie=prompt('Cookie（可留空）')||'';await action('/sources',{source,base_url,proxy_url,cookie})}
async function syncCatalog(actor:string,source:string){await action('/catalog/sync',{actor,source})}
onMounted(()=>{if(!auth.value)setup.value=true;refresh();pollTimer.value=window.setInterval(()=>{if(auth.value&&!document.hidden&&(jobs.value.some(j=>['pending','running'].includes(j.status))||devices.value.some(d=>d.online)||['downloads','devices','jobs'].includes(section.value)))refresh()},20000)})
onUnmounted(()=>{if(pollTimer.value)window.clearInterval(pollTimer.value)})
</script>
<template><div class="app-shell"><aside class="sidebar" :class="{open:mobileNav}"><div class="brand"><div class="brand-mark"><Film :size="20"/></div><div><strong>MediaShelf</strong><span>个人媒体管理</span></div><button class="icon-btn close-nav" @click="mobileNav=false"><X/></button></div><div class="workspace"><i></i>我的媒体空间<ChevronDown :size="14"/></div><div class="nav-label">工作台</div><nav><button v-for="n in nav" :key="n.id" :class="['nav-item',{active:section===n.id}]" @click="section=n.id as Section;mobileNav=false"><component :is="n.icon" :size="17"/><span>{{n.label}}</span><em v-if="n.id==='jobs'&&jobs.filter(j=>['pending','running'].includes(j.status)).length">{{jobs.filter(j=>['pending','running'].includes(j.status)).length}}</em></button></nav><div class="sidebar-bottom"><div class="sync-card"><Database/><div><b>{{devices.filter(d=>d.online).length}} / {{devices.length}} 设备在线</b><span>{{libraries.length}} 个媒体目录已连接</span></div></div><div class="profile"><div class="avatar">M</div><div><b>本地管理员</b><span>私人媒体库</span></div><button class="icon-btn" @click="logout"><LogOut/></button></div></div></aside><div v-if="mobileNav" class="scrim" @click="mobileNav=false"></div>
<main class="main"><header class="topbar"><button class="icon-btn mobile-menu" @click="mobileNav=true"><Menu/></button><div class="crumb">MediaShelf <i>/</i> <b>{{nav.find(n=>n.id===section)?.label}}</b></div><div class="top-actions"><label class="global-search"><Search/><input v-model="query" placeholder="搜索作品、编号、演员…" @input="section='library'"/><kbd>⌘ K</kbd></label><button class="icon-btn" title="刷新" @click="refresh"><RefreshCw :class="{spin:busy}"/></button><div class="avatar small">M</div></div></header><div v-if="error" class="toast error-toast"><CircleAlert/><span>{{error}}</span><button @click="error=''">×</button></div><div v-if="notice" class="toast success-toast"><Check/><span>{{notice}}</span><button @click="notice=''">×</button></div><div class="content">
<template v-if="section==='library'"><div class="page-heading"><div><div class="eyebrow">COLLECTION OVERVIEW</div><h1>媒体库</h1><p>集中浏览和管理你的个人收藏。</p></div><div class="heading-actions"><button class="btn secondary" :disabled="!libraries.length" @click="action(`/libraries/${encodeURIComponent(libraries[0]?.id||'')}/scan`)"><RefreshCw/>扫描目录</button><button class="btn primary" @click="add('library')"><Plus/>添加目录</button></div></div><div class="stat-grid"><div class="stat-card"><div class="stat-top">作品总数 <Film/></div><strong>{{works.length.toLocaleString()}}</strong><small>已索引作品</small><div class="stat-line"><i style="width:72%"/></div></div><div class="stat-card"><div class="stat-top">演员收藏 <UsersRound/></div><strong>{{actors.length.toLocaleString()}}</strong><small>正在关注的演员</small><div class="stat-line cyan"><i style="width:56%"/></div></div><div class="stat-card"><div class="stat-top">库内占用 <HardDrive/></div><strong>{{totalSize}}</strong><small>{{works.reduce((n,w)=>n+(w.files?.length||0),0)}} 个文件已登记</small><div class="stat-line purple"><i style="width:44%"/></div></div><div class="stat-card"><div class="stat-top">在线设备 <Monitor/></div><strong>{{devices.filter(d=>d.online).length}}<em> / {{devices.length}}</em></strong><small>最后连接状态</small><div class="device-indicator"><i v-for="d in devices.slice(0,8)" :key="d.id" :class="{online:d.online}"/></div></div></div><div class="section-head"><div><h2>所有作品 <span class="muted">{{filtered.length}}</span></h2><p>你的收藏都在这里。</p></div><div class="view-actions"><select v-model="statusFilter"><option value="">全部状态</option><option value="owned">已入库</option><option value="wanted">待收集</option><option value="partial">收集中</option><option value="complete">已收全</option></select><select v-model="actorFilter"><option value="">所有演员</option><option v-for="a in actors" :key="a.name">{{a.name}}</option></select><button class="btn secondary"><SlidersHorizontal/>筛选</button></div></div><div class="chip-row"><button :class="['chip',{chosen:!statusFilter}]" @click="statusFilter='';actorFilter=''">全部藏品</button><button v-for="s in [{id:'complete',label:'已收集'},{id:'partial',label:'收集中'},{id:'wanted',label:'待补充'}]" :key="s.id" :class="['chip',{chosen:statusFilter===s.id}]" @click="statusFilter=s.id">{{s.label}}</button><span class="muted tiny">最近添加 <ChevronDown/></span></div><div v-if="busy&&!works.length" class="loading-state"><LoaderCircle class="spin"/>正在读取媒体库…</div><div v-else-if="!filtered.length" class="empty-state"><div class="empty-art"><Film/></div><h3>{{works.length?'没有匹配的作品':'媒体库还没有作品'}}</h3><p>{{works.length?'尝试调整搜索或筛选条件。':'添加媒体目录，然后扫描本地文件建立收藏。'}}</p><button v-if="!works.length" class="btn primary" @click="add('library')"><Plus/>添加媒体目录</button></div><div v-else class="work-grid"><article v-for="w in filtered" :key="w.id" class="work-card" @click="selectWork(w)"><div class="poster"><img v-if="w.cover_url" :src="coverSrc(w.cover_url)" loading="lazy"/><div v-else class="poster-placeholder"><Film/><span>{{w.code||'NO COVER'}}</span></div><span class="collection-badge" :class="w.collection_status">{{w.collection_status==='complete'?'已收全':w.collection_status==='owned'?'已入库':w.collection_status==='partial'?'收集中':w.collection_status||'未归档'}}</span><button class="play-btn"><Play fill="currentColor"/></button></div><div class="work-info"><div class="work-code">{{w.code||'未识别编号'}} <span v-if="w.year">· {{w.year}}</span></div><h3>{{w.title||w.code||'未命名作品'}}</h3><div class="actor-list">{{w.actors?.slice(0,3).join(' · ')||'未标记演员'}}</div><div class="work-meta"><div class="stars"><Star fill="currentColor"/> <b>{{w.rating??w.source_rating??'—'}}</b></div><div class="progress-mini"><span v-for="(v,k) in [w.progress?.compression,w.progress?.cutting,w.progress?.translation]" :key="k" :class="String(v)"/></div></div></div></article></div><div class="page-footer">显示 {{filtered.length}} / {{works.length}} 部作品</div></template>
<template v-else-if="section==='actors'"><div class="page-heading"><div><div class="eyebrow">ACTOR COLLECTIONS</div><h1>演员收藏</h1><p>设置每位演员的收集目标与策略。</p></div><button class="btn primary" @click="section='discover';loadCatalog()"><Plus/>浏览演员目录</button></div><div class="actor-toolbar"><label class="global-search local"><Search/><input v-model="query" placeholder="搜索演员姓名…"/></label><span class="muted">共 {{actors.length}} 位演员</span></div><div v-if="!actors.length" class="empty-state"><UsersRound/><h3>还没有演员收藏数据</h3><p>作品扫描后会自动整理演员。</p></div><div v-else class="table-wrap"><table><thead><tr><th>演员</th><th>作品数</th><th>收集策略</th><th>目标数量</th><th>完成情况</th></tr></thead><tbody><tr v-for="a in actors.filter(x=>!query||x.name.toLowerCase().includes(query.toLowerCase()))" :key="a.name"><td><b>{{a.name}}</b></td><td>{{a.count}}</td><td><select v-model="a.policy" @change="saveActor(a)"><option value="complete">尽量收全</option><option value="selective">精选收藏</option><option value="follow">只关注</option></select></td><td><input class="target-input" type="number" min="0" v-model.number="a.target" @change="saveActor(a)"/></td><td><div class="table-progress"><div><i :style="{width:Math.min(100,a.target?100*a.count/a.target:0)+'%'}"/></div>{{a.target?Math.min(100,Math.round(100*a.count/a.target)):0}}%</div></td></tr></tbody></table></div></template>
<template v-else-if="section==='devices'"><div class="page-heading"><div><div class="eyebrow">DEVICES & LIBRARIES</div><h1>设备与目录</h1><p>注册运行本地代理的设备，并配置媒体目录。</p></div><button class="btn primary" @click="add('device')"><Plus/>注册设备</button></div><div class="subhead"><h2>已注册设备</h2></div><div class="device-grid"><div v-for="d in devices" :key="d.id" class="device-card"><div class="device-top"><div class="device-icon"><Monitor/></div><i class="status-dot" :class="{online:d.online}"/></div><h3>{{d.name}}</h3><p>{{d.online?'运行正常':'当前离线'}}</p><div class="device-foot"><span>最近在线</span><b>{{d.last_seen||'尚未连接'}}</b></div></div><div v-if="!devices.length" class="empty-inline">尚未注册设备。先创建设备，再在本地代理填写生成的设备令牌。</div></div><div class="section-head"><div><h2>媒体目录 <span class="muted">{{libraries.length}}</span></h2><p>目录由设备代理扫描；服务端不会移动文件。</p></div><button class="btn secondary" @click="add('library')"><Plus/>添加目录</button></div><div class="table-wrap"><table><thead><tr><th>目录名称</th><th>本地路径</th><th>设备</th><th>OpenList</th><th>操作</th></tr></thead><tbody><tr v-for="l in libraries" :key="l.id"><td><b>{{l.name}}</b></td><td class="mono">{{l.path}}</td><td>{{devices.find(d=>d.id===l.device_id)?.name||l.device_id||'—'}}</td><td>{{l.openlist_base||'未配置'}}</td><td><button class="text-btn" @click="action(`/libraries/${encodeURIComponent(l.id)}/scan`)">扫描 <ArrowUpRight/></button></td></tr></tbody></table></div></template>
<template v-else-if="section==='tools'"><div class="page-heading"><div><div class="eyebrow">LOCAL WORKFLOW</div><h1>本地工具</h1><p>配置安装在设备上的处理工具，通过代理安全启动。</p></div><button class="btn primary" @click="add('tool')"><Plus/>添加工具</button></div><div v-if="!tools.length" class="empty-state"><Wrench/><h3>还没有配置工具</h3><p>添加本地工具路径后，可从这里向对应设备提交启动任务。</p></div><div v-for="t in tools" :key="t.id" class="tool-card"><div class="tool-icon"><Wrench/></div><div class="tool-copy"><h3>{{t.name}}</h3><p class="mono">{{t.path}}</p><span>{{devices.find(d=>d.id===t.device_id)?.name||t.device_id}}</span></div><button class="btn secondary" @click="action(`/tools/${encodeURIComponent(t.id)}/launch`)"><Play/>启动</button></div></template>
<template v-else-if="section==='downloads'"><div class="page-heading"><div><div class="eyebrow">DOWNLOAD STATION</div><h1>下载管理</h1><p>查看并管理已连接的 qBittorrent 下载器。</p></div><div class="heading-actions"><button class="btn secondary" :disabled="!downloaders.length" @click="addTorrent"><Plus/>添加种子</button><button class="btn primary" @click="add('downloader')"><Plus/>添加下载器</button></div></div><div v-if="!downloaders.length" class="empty-state"><Download/><h3>还没有连接下载器</h3><p>添加 qBittorrent WebUI 后，在这里查看种子状态和队列。</p><button class="btn primary" @click="add('downloader')">连接下载器</button></div><template v-else><div class="downloader-banner"><Download/><div><b>{{downloaders[0].name}}</b><span>{{downloaders[0].url}} · 凭据由服务端保护</span></div><button class="btn secondary" @click="refresh"><RefreshCw/>同步状态</button></div><div class="download-stats"><div><span>任务总数</span><b>{{torrents.length}}</b></div><div><span>下载中</span><b>{{torrents.filter(t=>t.state?.includes('down')).length}}</b></div><div><span>做种中</span><b>{{torrents.filter(t=>t.state?.includes('up')).length}}</b></div></div><div class="table-wrap"><table><thead><tr><th>任务名称</th><th>状态</th><th>进度</th><th>大小</th><th>速度</th><th>操作</th></tr></thead><tbody><tr v-for="t in torrents" :key="t.hash"><td><b>{{t.name}}</b></td><td>{{t.state}}</td><td>{{Math.round((t.progress||0)*100)}}%</td><td>{{(t.size/1024**3).toFixed(1)}} GB</td><td>{{(t.dlspeed/1024**2).toFixed(1)}} MB/s</td><td class="torrent-actions"><button class="text-btn" @click="action(`/downloaders/${encodeURIComponent(downloaders[0].id)}/action`,{action:t.state?.includes('down')?'stop':'start',hashes:[t.hash],delete_files:false})">{{t.state?.includes('down')?'暂停':'继续'}}</button><button class="text-btn" @click="manageTorrent(t,'category')">分类</button><button class="text-btn" @click="manageTorrent(t,'tags')">标签</button><button class="text-btn" @click="manageTorrent(t,'limits')">限速</button><button class="text-btn danger-text" @click="confirmDelete(t)">删除任务</button></td></tr></tbody></table><div v-if="!torrents.length" class="empty-inline">下载器中没有任务。</div></div></template></template>
<template v-else-if="section==='feeds'"><div class="page-heading"><div><div class="eyebrow">RSS DISCOVERY</div><h1>RSS 订阅</h1><p>发现新发布内容，再由你审核是否加入下载。</p></div><button class="btn primary" @click="add('feed')"><Plus/>添加订阅</button></div><div class="callout"><ShieldCheck/><div><b>下载前人工确认</b><span>RSS 只用于发现和补漏；匹配项会进入候选列表，不会自动开始下载。</span></div></div><div class="feed-list"><div v-for="f in feeds" :key="f.id" class="feed-row"><Rss/><div><b>{{f.name}}</b><span>{{f.url}}</span><small>包含：{{f.include||'无规则'}}　排除：{{f.exclude||'无'}}</small></div><button class="btn secondary" @click="action(`/feeds/${encodeURIComponent(f.id)}/refresh`)"><RefreshCw/>刷新</button></div><div v-if="!feeds.length" class="empty-inline">还没有 RSS 订阅。</div></div><div class="section-head"><div><h2>待审核候选 <span class="muted">{{candidates.length}}</span></h2><p>检查编号、重复状态和来源后再决定是否下载。</p></div></div><div v-for="c in candidates.filter(c=>!['ignored','downloaded'].includes(c.status))" :key="c.id" class="candidate-row"><span class="candidate-badge">{{c.owned?'已拥有':c.in_queue?'队列中':'新发现'}}</span><div><b>{{c.code}} · {{c.title}}</b><small>{{c.source}} · {{c.url}}</small></div><button class="text-btn" @click="action(`/candidates/${encodeURIComponent(c.id)}`,{status:'ignored'})">忽略</button><button class="btn primary small-btn" :disabled="!downloaders.length||c.owned||c.in_queue" @click="action(`/candidates/${encodeURIComponent(c.id)}/download`,{downloader_id:downloaders[0]?.id,save_path:'',category:''})"><Download/>加入下载</button></div></template>
<template v-else-if="section==='discover'"><div class="page-heading"><div><div class="eyebrow">DISCOVER & EXPLORE</div><h1>发现与推荐</h1><p>根据现有收藏浏览服务端推荐和演员目录。</p></div><button class="btn secondary" @click="refresh"><RefreshCw/>刷新推荐</button></div><div class="section-head"><div><h2><Sparkles/>为你推荐</h2><p>推荐结果来自服务端分析。</p></div></div><div class="recommend-grid"><div v-for="r in recommendations" :key="r.work?.id" class="recommend-card" @click="selectWork(r.work)"><img v-if="r.work?.cover_url" :src="coverSrc(r.work.cover_url)"/><div v-else class="poster-placeholder"><Film/></div><div><b>{{r.work?.code}} · {{r.work?.title}}</b><p>{{r.reason}}</p></div></div><div v-if="!recommendations.length" class="empty-inline">目前没有推荐结果。</div></div><div class="section-head"><div><h2>演员推荐</h2><p>为收藏补充新的关注方向。</p></div></div><div v-for="r in actorRecs" :key="r.name" class="feed-row"><div class="actor-avatar">{{r.name.slice(0,1)}}</div><b>{{r.name}}</b><span>{{r.reason}}</span><em>{{Math.round((r.score||0)*100)}} 分</em></div><div class="section-head"><div><h2>数据源</h2><p>配置可用的作品目录适配器。</p></div><button class="btn secondary" @click="addSource"><Plus/>配置来源</button></div><div v-for="s in sources" :key="s.source" class="feed-row"><Database/><div><b>{{s.source}}</b><span>{{s.base_url||'默认地址'}} · {{s.proxy_url||'未配置代理'}}</span></div><button class="btn secondary" :disabled="!actorFilter" @click="syncCatalog(actorFilter,s.source)">同步所选演员</button></div><div v-for="s in syncs.filter(x=>x.error)" :key="s.id" class="toast error-toast"><CircleAlert/><span>{{s.source}} / {{s.actor}}：{{s.error}}（已收录 {{s.count||0}} 项，尚未完成）</span></div><div class="section-head"><div><h2>演员作品目录</h2><p>查询服务端已连接的数据源。</p></div><div class="view-actions"><select v-model="actorFilter"><option value="">所有演员</option><option v-for="a in actors" :key="a.name">{{a.name}}</option></select><button class="btn secondary" @click="loadCatalog">查询目录</button></div></div><div v-for="w in catalog" :key="w.id||w.code" class="catalog-row"><b>{{w.code}} · {{w.title}}</b><span>{{w.year||'年份未知'}} · {{w.actors?.join('、')}}</span><em>{{w.owned?'已拥有':'未入库'}}</em></div><div v-if="!catalog.length" class="empty-inline">选择演员并查询目录；若数据源不可用，页面会显示服务端错误。</div></template>
<template v-else-if="section==='jobs'"><div class="page-heading"><div><div class="eyebrow">BACKGROUND ACTIVITY</div><h1>任务队列</h1><p>查看设备扫描、工具启动和下载操作的执行状态。</p></div><button class="btn secondary" @click="refresh"><RefreshCw/>刷新任务</button></div><div class="job-summary"><div>等待中 <b>{{jobs.filter(j=>j.status==='pending').length}}</b></div><div>运行中 <b>{{jobs.filter(j=>j.status==='running').length}}</b></div><div>已完成 <b>{{jobs.filter(j=>['done','completed'].includes(j.status)).length}}</b></div><div>失败 <b>{{jobs.filter(j=>j.status==='failed').length}}</b></div></div><div v-for="j in jobs" :key="j.id" class="job-row"><div class="job-type-icon"><LoaderCircle v-if="j.status==='running'" class="spin"/><Check v-else-if="['done','completed'].includes(j.status)"/><CircleAlert v-else-if="j.status==='failed'"/><Clock3 v-else/></div><div class="job-detail"><b>{{j.type}}</b><span>{{j.device_id}} · {{j.created_at}}</span><small>{{j.result}}</small></div><span class="job-status">{{j.status}}</span></div><div v-if="!jobs.length" class="empty-inline">任务队列为空。</div></template>
<template v-else-if="section==='settings'"><div class="page-heading"><div><div class="eyebrow">PREFERENCES & DATA</div><h1>设置</h1><p>管理服务偏好、数据库备份和登录状态。</p></div><button class="btn secondary" @click="logout"><LogOut/>退出登录</button></div><div class="settings-columns"><div><section class="settings-card"><div class="settings-title"><Settings2/><div><h2>服务设置</h2><p>保存到服务端的全局配置。</p></div></div><label class="field">媒体类型分类目录<input v-model="settings.category_dirs" placeholder="例如：2D, Anime, VR"/></label><label class="field">默认收藏状态<select v-model="settings.default_collection_status"><option value="wanted">待收集</option><option value="partial">收集中</option><option value="complete">已收全</option></select></label><label class="toggle-line"><span><b>启用演员作品推荐</b><small>使用本地收藏生成相关建议</small></span><input type="checkbox" v-model="settings.actor_recommendations_enabled"/></label><button class="btn primary" @click="saveSettings">保存设置</button></section><section class="settings-card"><div class="settings-title"><Database/><div><h2>数据库备份</h2><p>导出或恢复整个 MediaShelf 数据库。</p></div></div><div class="backup-actions"><button class="btn secondary" @click="backup"><ArrowUpRight/>导出备份 JSON</button><label class="btn secondary upload-btn"><FolderOpen/>选择备份文件<input type="file" accept="application/json,.json" @change="restore"/></label></div><p class="warning-note"><CircleAlert/>恢复会覆盖当前数据库，并需要二次确认。</p></section></div><aside class="settings-side"><div class="account-card"><div class="account-avatar">M</div><h3>本地管理员</h3><p>服务端身份验证已启用</p><div class="account-state">● 已安全连接</div></div><div class="settings-tip"><ShieldCheck/><b>数据保存在你的设备</b><span>MediaShelf 使用本地服务与 SQLite 存储。API 错误会直接显示，页面不会填入演示数据。</span></div></aside></div></template>
</div><footer class="app-footer"><span>MediaShelf · 私人媒体管理</span><span>本地优先 <i/></span></footer></main>
<div v-if="modal&&selected" class="modal-backdrop" @click.self="modal=false"><div class="detail-modal"><button class="modal-close icon-btn" @click="modal=false"><X/></button><div class="detail-cover"><img v-if="selected.cover_url" :src="coverSrc(selected.cover_url)"/><div v-else class="poster-placeholder"><Film/></div><span>{{selected.code}}</span></div><div class="detail-body"><div class="eyebrow">WORK DETAILS</div><h2>{{selected.title||selected.code}}</h2><p>{{selected.code}} · {{selected.year}} · {{selected.kind}}</p><label class="field">作品标题<input v-model="selected.title"/></label><label class="field">演员（逗号分隔）<input :value="selected.actors?.join(', ')" @input="selected.actors=($event.target as HTMLInputElement).value.split(',').map(s=>s.trim()).filter(Boolean)"/></label><label class="field">收藏状态<select v-model="selected.collection_status"><option value="owned">已入库</option><option value="wanted">待收集</option><option value="partial">收集中</option><option value="complete">已收全</option></select></label><div class="rating-field">我的评分 <button v-for="n in 5" :key="n" @click="selected!.rating=n"><Star :fill="(selected.rating||0)>=n?'currentColor':'none'"/></button> {{selected.rating??'未评分'}}</div><div class="progress-fields"><b>处理进度</b><label>压制<select v-model="selected.progress!.compression"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="not_needed">不需要</option></select></label><label>剪辑<select v-model="selected.progress!.cutting"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="not_needed">不需要</option></select></label><label>翻译<select v-model="selected.progress!.translation"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">已完成</option><option value="not_needed">不需要</option></select></label><label><input type="checkbox" v-model="selected.progress!.verified"/> 已核验</label></div><div class="detail-files"><b>关联文件 · {{selected.files?.length||0}}</b><div v-for="f in selected.files" :key="f.id" class="file-row"><FolderOpen/><span>{{f.relative_path}}</span><em>{{(f.size/1024**3).toFixed(2)}} GB</em><i>{{f.missing?'缺失':'可用'}}</i><a v-if="openListUrl(f)" :href="openListUrl(f)" target="_blank" rel="noopener noreferrer">OpenList</a><div class="file-progress-controls"><label>压制<select v-model="f.progress.compression" @change="saveFileProgress(selected!,f)"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">完成</option><option value="not_needed">不需要</option></select></label><label>剪辑<select v-model="f.progress.cutting" @change="saveFileProgress(selected!,f)"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">完成</option><option value="not_needed">不需要</option></select></label><label>翻译<select v-model="f.progress.translation" @change="saveFileProgress(selected!,f)"><option value="pending">待处理</option><option value="in_progress">进行中</option><option value="done">完成</option><option value="not_needed">不需要</option></select></label><label class="verified"><input type="checkbox" v-model="f.progress.verified" @change="saveFileProgress(selected!,f)"/>核验</label></div></div><p v-if="!selected.files?.length">没有关联文件</p></div><div class="modal-actions"><button class="btn secondary" @click="modal=false">取消</button><button class="btn primary" @click="saveWork">保存修改</button></div></div></div></div>
<div v-if="setup" class="login-backdrop"><form class="login-card" @submit.prevent="login"><div class="login-mark"><Film/></div><div class="eyebrow">PRIVATE MEDIA LIBRARY</div><h1>欢迎回来</h1><p>登录你的 MediaShelf 本地媒体库。</p><label class="field">服务密码<div class="password-wrap"><input v-model="password" :type="showPassword?'text':'password'" placeholder="输入 MEDIASHELF_PASSWORD" autofocus/><button type="button" class="icon-btn" @click="showPassword=!showPassword"><Eye v-if="showPassword"/><EyeOff v-else/></button></div></label><div v-if="error" class="login-error">{{error}}</div><button class="btn primary login-btn" type="submit" :disabled="working">{{working?'正在验证…':'登录媒体库'}}</button><small>使用服务端环境变量 MEDIASHELF_PASSWORD。</small></form></div></div></template>









